steps.code:
const record = flow.trigger.data;
const missing = ['EMCo', 'Equipment', 'Type', 'Status'].filter((field) => record?.[field] == null || String(record[field]).trim() === '');
if (missing.length) throw new Error(`Missing required equipment fields: ${missing.join(', ')}`);
return record;

const source = flow.trigger.data;
const existing = flow.step('eq-check').output?.[0] ?? {};
const manufacturer = flow.step('lk-man').output?.[0];
const group = flow.step('lk-grp').output?.[0];
const job = flow.step('look-ivo-job').output?.[0];
const text = (value) => value == null ? null : String(value).trim();
const vin = text(source.VINNumber);
const validVin = /^[A-HJ-NPR-Z0-9]{17}$/.test(vin ?? '');
const year = Number.parseInt(text(source.ModelYr), 10);
return { uuid: existing.uuid ?? null, equipmentId: existing.equipmentId ?? null, equipmentName: existing.equipmentName ?? text(source.Equipment), equipmentYear: Number.isNaN(year) || year === 0 ? null : year, equipmentManufacturerId: manufacturer?.equipmentManufacturerId ?? null, equipmentModel: text(source.Model) || ' ', equipmentDescription: text(source.Description), serialNumber: validVin ? ' ' : (vin || ' '), vinNumber: validVin ? vin : null, equipmentGroupId: group?.equipmentGroupId ?? null, companyId: Number(flow.config.ivoCompanyId) || null, currentTrackVoJobId: job?.jobId ?? null, isDeleted: false, createdByUserId: Number(flow.config.createdByUserId), isActive: text(source.Status) === 'A', isLocationTracked: true, isScheduleable: false, isScheduleVo: false, isRental: text(source.OwnershipStatus) === 'R', accountingCode: existing.accountingCode ?? text(source.Equipment), licenseNumber: text(source.LicensePlateNo) || '' };

const matches = flow.step('eq-check').output ?? [];
if (matches.length > 1) throw new Error('Multiple IVO equipment records match the Vista equipment code.');
return matches.length === 1;

const record = flow.trigger.data;
const missing = ['JCCo', 'Contract', 'Item', 'KeyID'].filter((field) => record?.[field] == null || String(record[field]).trim() === '');
if (missing.length) throw new Error(`Missing required contract item fields: ${missing.join(', ')}`);
return record;

const source = flow.trigger.data;
const existing = flow.step('item-check').output?.[0] ?? {};
const job = flow.step('contract-job').output?.[0];
const text = (value) => value == null ? null : String(value).trim();
const quantity = Number.parseFloat(source.ContractUnits);
return { uuid: existing.uuid ?? null, itemCodeId: existing.itemCodeId ?? null, jobId: job?.jobId ?? null, itemCode: (text(source.Item) ?? '').slice(0, 100), quantity: Number.isNaN(quantity) ? null : quantity, unitOfMeasure: text(source.UM)?.slice(0, 100) ?? null, description: (text(source.Description) ?? '').slice(0, 100), note: text(source.Notes)?.slice(0, 100) ?? null, accountingCode: text(source.TaxCode)?.slice(0, 100) ?? null, estimatingCode: text(source.TaxCode)?.slice(0, 100) ?? null, isActive: true };

const matches = flow.step('item-check').output ?? [];
if (matches.length > 1) throw new Error('Multiple IVO job item codes match this job and Vista item.');
return matches.length === 1;
